                    executionContext: execution,
                    now,
                    reason: 'task-drive',
                });
                await taskExecutionPersistence.intentTerminalization.terminalize({
                    taskId,
                    state: 'failed',
                    failureCode: 'task-drive-failed',
                    now,
                    claimedOwnerEpoch: execution.token.epoch,
                });
            },
        },
